    make(4, "降雨後，部分雨水滲入土壤並補注地下水。下列判斷何者正確？", {"A": "雨水進入地下後就不再屬於水圈", "B": "土壤是大氣圈的一部分", "C": "水從大氣圈進入水圈中的地下水系統", "D": "地下水只能由岩石圈變成"}, "C", "降雨來自大氣圈中的水，滲入後成為地下水，仍屬水圈的一部分；土壤與岩層提供儲存和流動的地質環境。", "追蹤水的狀態與位置改變，避免把進入地下誤認成離開水圈。", ["確認雨水降落前在大氣圈。", "水進入土壤孔隙並向下滲流。", "地下水仍是水圈的一部分。", "岩石與土壤屬岩石圈環境，會影響水流。", "所以這是大氣圈與水圈及岩石圈環境的交互作用。"], "medium"),
    make(5, "海岸剖面顯示浪潮反覆沖刷岩壁並帶走砂粒。最適當的證據結論是？", {"A": "水圈的海水運動能改變岩石圈表面，但需長期資料確認侵蝕量", "B": "一次照片就能證明所有海岸都以同速率侵蝕", "C": "砂粒被大氣圈製造出來，與海水無關", "D": "岩石圈會主動把海水推走"}, "A", "海水屬水圈，岩壁與砂粒屬岩石圈表面；浪潮可造成侵蝕與搬運，但侵蝕速率需多次觀測或量測資料支持。", "先判斷圈層關係，再分辨直接觀察和過度外推。", ["辨認海水是水圈物質。", "辨認岩壁與砂粒是岩石圈表面物質。", "浪潮可對岩壁產生侵蝕與搬運。", "一次影像只顯示當下，不足以量出長期速率。", "因此應採用有條件且保留資料限制的結論。"], "hard"),
    make(6, "地表植物蒸散把水蒸氣送入空氣，之後可能形成雲。這表示地球圈層是？", {"A": "彼此封閉的三個盒子", "B": "可透過物質與能量交換而互相影響的系統", "C": "只有水圈會改變，其他圈層不受影響", "D": "只有岩石圈存在物質循環"}, "B", "植物把水從土壤與生物系統帶到大氣，顯示圈層之間有物質和能量交換，不是彼此完全隔離的封閉盒。", "從一條物質移動路徑判斷系統是否互相連結。", ["找出水的起點與終點。", "水由地表或生物系統進入大氣。", "雲的形成又可能把水帶回地表。", "這是一條跨圈層物質循環路徑。", "所以地球圈層是可交換物質與能量的互動系統。"], "medium"),
    make(7, "若圖中箭頭由雲指向河流，最可能代表哪一種過程？", {"A": "河流把岩石變成雲", "B": "太陽系把河水吸到太空", "C": "降雨使大氣圈中的水進入水圈地表水", "D": "雲只代表固體岩石"}, "C", "雲位於大氣圈，河流屬水圈；箭頭由雲到河流可表示降雨或降水，使水由大氣進入地表水系統。", "讀流程圖時先判定箭頭起點與終點各自的圈層。", ["辨認箭頭起點雲屬大氣圈。", "辨認終點河流屬水圈。", "大氣水降落可形成河流水量。", "這符合降水造成的物質轉移。", "所以選大氣圈到水圈的降雨。"], "easy"),
    make(8, "下列哪一項是讀取三圈層剖面圖時較可靠的作法？", {"A": "只看圖上最醒目的顏色就下結論", "B": "先記錄物質、位置與箭頭，再判斷交換方向並說明證據", "C": "只要看到水就判定整張圖是水圈", "D": "忽略圖例，直接把圖上距離當實際比例"}, "B", "科學讀圖要先辨認可觀察的物質和位置，再追蹤箭頭與交換方向，並引用圖例或資料作為證據；不能只靠顏色或單一關鍵字。", "依觀察、解釋、證據三步驟讀圖。", ["先記錄圖中的物質與所在位置。", "確認圖例和箭頭的意義。", "追蹤哪個圈層的物質移向哪裡。", "把判斷連回圖面或資料證據。", "最後說明圖面比例或資料不足等限制。"], "hard"),
    make(9, "岩石風化後形成土壤，降雨又把土壤中的細粒帶入河流。此例至少顯示？", {"A": "岩石圈物質可受水圈作用而搬運，並非圈層各自獨立", "B": "土壤屬於外太空，不受地球系統影響", "C": "河流不屬水圈，因為含有泥沙", "D": "風化只會改變大氣圈"}, "A", "岩石與土壤屬岩石圈相關物質，降雨和河流屬水圈；水的作用可搬運風化產物，顯示圈層交互作用。", "同時辨認物質來源、作用力與搬運終點。", ["確認岩石風化產生土壤與細粒。", "這些固體物質屬岩石圈相關環境。", "降雨與河流提供水圈作用。", "水將細粒搬入河流。", "所以岩石圈物質受水圈作用而轉移。"], "medium"),
